ead > div { display: grid; gap: 2px; }.result-head strong { font-size: 10px; }.result-head small { color: #6b8396; font-size: 8px; }.result-head > span { padding: 3px 5px; border-radius: 3px; color: #879baa; background: #253443; font-size: 7px; }.result-head > span.approved { color: #65daa4; background: #173a31; }.result-head > span.rejected { color: #ff91a0; background: #3a2028; }.result-videos { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }.result-videos video { width: 100%; aspect-ratio: 16/9; background: #050b10; object-fit: contain; }.outcome-form { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 7px; margin-top: 9px; }.outcome-form label { display: grid; gap: 4px; color: #8299aa; font-size: 8px; }.outcome-form label.notes { grid-column: 1/-1; }.outcome-form input,.outcome-form select,.outcome-form textarea { width: 100%; min-width: 0; padding: 7px; border: 1px solid #29435f; border-radius: 4px; outline: 0; resize: vertical; background: #091522; color: #d9e6ed; font-size: 8px; }.save-result { display: flex; align-items: center; justify-content: space-between; margin-top: 8px; color: #65b98f; font-size: 8px; }.save-result button { padding: 7px 10px; border: 0; border-radius: 4px; cursor: pointer; background: #64c9e8; color: #07131c; font-size: 8px; font-weight: 650; }.save-result button:disabled { opacity: .4; }
